/*
 * The Space types' DSP and ops (S095 P1 plan §4; §S18). Built with the DSP
 * fast-math policy (Makefile). Loop rules (plan §3): no division, libm call
 * or double in a frame loop; laws with libm run in write_param (a row
 * change), never per block or per frame.
 */





#include <math.h>
#include <string.h>

/*
 * Size policy (§S18): everything outside a frame loop is compiled for size.
 * A per-file -Os is lost under -flto, a per-function attribute is not
 * (measured: space_delayProcess 1,448 -> 1,134 B). Its cost is per block or
 * per row change, so the instruction gates move by at most a few tenths
 * per frame.
 */
#if defined(__clang__)
#define SPACE_ONCE                    /* host tests (clang) */
#define SPACE_SIZE                    /* host tests (clang): no such attribute */
#define SPACE_LOOP __attribute__((noinline))
#else
/*
 * One iteration per loop body (no unrolling), so each frame loop's ELF
 * length is one frame or one tick: space_cpu.py multiplies by the known
 * iteration counts.
 */
#define SPACE_ONCE _Pragma("GCC unroll 1")
#define SPACE_SIZE __attribute__((optimize("Os")))
/* The frame loops: -Ofast, but one copy (no unswitching, peeling or unrolling). */
#define SPACE_LOOP __attribute__((noinline, optimize("no-unswitch-loops", "no-peel-loops", "no-unroll-loops", "no-predictive-commoning")))
#endif

/* ---------------------------------------------------------------------- */
/* Geometry and constants                                                  */
/* ---------------------------------------------------------------------- */

/* The tape (plan §4.1): Hermite reads one frame behind and two ahead. */
#define SPACE_TAPE_GUARD     3u      /* frames duplicated past the end */
#define SPACE_TAPE_LANES     2u      /* the Delay's L,R int16 frame */
/*
 * The shortest delay (§S18): a whole block plus the Hermite neighbours, so
 * every read of a block lands on frames written before it and the read
 * pass can run ahead of the write pass. CrumpBit's rows 0-1 (2 and ~10
 * samples) play this floor (0.8 ms).
 */
#define SPACE_D_MIN          36.0f
#define SPACE_SPEED_MIN      0.25f   /* D3: the 1/4 floor */
/* Glide: one-pole per block, about 150 ms (plan §4.1). */
#define SPACE_GLIDE_K32      0.0048252f
/* Ducking follower per block: 2 ms attack, 200 ms release (O1). */
#define SPACE_DUCK_ATK       0.30f
#define SPACE_DUCK_REL       0.0036f

